    private static Block register(BlockItemId id, Function<BlockBehaviour.Properties, Block> blockFactory, BlockBehaviour.Properties properties) {
        Block block = register(id.block(), blockFactory, properties);
        BlockItem blockItem;

        if (id.block().identifier().getPath().contains("netherite") || id.block().identifier().getPath().contains("player")) {
            blockItem = new BlockItem(block, new Item.Properties().useBlockDescriptionPrefix().setId(id.item()).fireResistant());
        } else {
            blockItem = new BlockItem(block, new Item.Properties().useBlockDescriptionPrefix().setId(id.item()));
        }

        Registry.register(BuiltInRegistries.ITEM, id.item(), blockItem);

        return block;
    }

    private static Block registerStandingVariant(BlockItemId id, Function<BlockBehaviour.Properties, Block> blockFactory, BlockBehaviour.Properties properties) {
        Block block = register(id.block(), blockFactory, properties);

        return block;
    }

    private static Block registerWallVariant(ResourceKey<Block> id, Function<BlockBehaviour.Properties, Block> blockFactory, BlockBehaviour.Properties properties, Block standingVariant) {
        Block block = register(id, blockFactory, properties.overrideLootTable(standingVariant.getLootTable()).overrideDescription(standingVariant.getDescriptionId()));

        return block;
    }

    private static Block registerLiquid(ResourceKey<Block> id, Function<BlockBehaviour.Properties, Block> blockFactory, BlockBehaviour.Properties properties) {
        Block block = register(id, blockFactory, properties.replaceable().noCollision().strength(100.0F).pushReaction(PushReaction.DESTROY).noLootTable().liquid().sound(SoundType.EMPTY));

        return block;
    }

    private static Block register(ResourceKey<Block> id, Function<BlockBehaviour.Properties, Block> factory, BlockBehaviour.Properties properties) {
        Block block = (Block)factory.apply(properties.setId(id));
        return Registry.register(BuiltInRegistries.BLOCK, id, block);
    }

    public static void initialize() {

    }
